	  'actor',
	  'any', // contextual
	  'associatedtype',
	  'async',
	  'await',
	  /as\?/, // operator
	  /as!/, // operator
	  'as', // operator
	  'borrowing', // contextual
	  'break',
	  'case',
	  'catch',
	  'class',
	  'consume', // contextual
	  'consuming', // contextual
	  'continue',
	  'convenience', // contextual
	  'copy', // contextual
	  'default',
	  'defer',
	  'deinit',
	  'didSet', // contextual
	  'distributed',
	  'do',
	  'dynamic', // contextual
	  'each',
	  'else',
	  'enum',
	  'extension',
	  'fallthrough',
	  /fileprivate\(set\)/,
	  'fileprivate',
	  'final', // contextual
	  'for',
	  'func',
	  'get', // contextual
	  'guard',
	  'if',
	  'import',
	  'indirect', // contextual
	  'infix', // contextual
	  /init\?/,
	  /init!/,
	  'inout',
	  /internal\(set\)/,
	  'internal',
	  'in',
	  'is', // operator
	  'isolated', // contextual
	  'nonisolated', // contextual
	  'lazy', // contextual
	  'let',
	  'macro',
	  'mutating', // contextual
	  'nonmutating', // contextual
	  /open\(set\)/, // contextual
	  'open', // contextual
	  'operator',
	  'optional', // contextual
	  'override', // contextual
	  'package',
	  'postfix', // contextual
	  'precedencegroup',
	  'prefix', // contextual
	  /private\(set\)/,
	  'private',
	  'protocol',
	  /public\(set\)/,
	  'public',
	  'repeat',
	  'required', // contextual
	  'rethrows',
	  'return',
	  'set', // contextual
	  'some', // contextual
	  'static',
	  'struct',
	  'subscript',
	  'super',
	  'switch',
	  'throws',
	  'throw',
	  /try\?/, // operator
	  /try!/, // operator
	  'try', // operator
	  'typealias',
	  /unowned\(safe\)/, // contextual
	  /unowned\(unsafe\)/, // contextual
	  'unowned', // contextual
	  'var',
	  'weak', // contextual
	  'where',
	  'while',
	  'willSet' // contextual
