	const numberSignKeywords = [
	  '#colorLiteral',
	  '#column',
	  '#dsohandle',
	  '#else',
	  '#elseif',
	  '#endif',
	  '#error',
	  '#file',
	  '#fileID',
	  '#fileLiteral',
	  '#filePath',
	  '#function',
	  '#if',
	  '#imageLiteral',
	  '#keyPath',
	  '#line',
	  '#selector',
	  '#sourceLocation',
	  '#warning'
	];

