	  'abs',
	  'all',
	  'any',
	  'assert',
	  'assertionFailure',
	  'debugPrint',
	  'dump',
	  'fatalError',
	  'getVaList',
	  'isKnownUniquelyReferenced',
	  'max',
	  'min',
	  'numericCast',
	  'pointwiseMax',
	  'pointwiseMin',
	  'precondition',
	  'preconditionFailure',
	  'print',
	  'readLine',
	  'repeatElement',
	  'sequence',
	  'stride',
	  'swap',
	  'swift_unboxFromSwiftValueWithType',
	  'transcode',
	  'type',
	  'unsafeBitCast',
	  'unsafeDowncast',
	  'withExtendedLifetime',
	  'withUnsafeMutablePointer',
	  'withUnsafePointer',
	  'withVaList',
	  'withoutActuallyEscaping',
	  'zip'
