	  operatorHead,
	  /[\u0300-\u036F]/,
	  /[\u1DC0-\u1DFF]/,
	  /[\u20D0-\u20FF]/,
	  /[\uFE00-\uFE0F]/,
	  /[\uFE20-\uFE2F]/
