	      TUPLE_ELEMENT_NAME,
	      ...COMMENTS,
	      REGEXP,
	      ...KEYWORD_MODES,
	      ...BUILT_INS,
	      ...OPERATORS,
	      NUMBER,
	      STRING,
	      ...IDENTIFIERS,
	      ...ATTRIBUTES,
	      TYPE
